import{_ as i,D as o,o as r,c as t,j as e,a,I as d,w as h,am as n}from"./chunks/framework.DXw8qDd0.js";const f=JSON.parse('{"title":"Codex归档会话后会话去哪里了","description":"","frontmatter":{"title":"Codex归档会话后会话去哪里了","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex归档会话后会话去哪里了.md","filePath":"笔记/Codex/Codex归档会话后会话去哪里了.md"}'),s={name:"笔记/Codex/Codex归档会话后会话去哪里了.md"},c=n('<h1 id="codex-归档会话后-会话去哪里了" tabindex="-1">Codex 归档会话后，会话去哪里了？ <a class="header-anchor" href="#codex-归档会话后-会话去哪里了" aria-label="Permalink to &quot;Codex 归档会话后，会话去哪里了？&quot;">​</a></h1><hr><h2 id="归档是什么" tabindex="-1">归档是什么 <a class="header-anchor" href="#归档是什么" aria-label="Permalink to &quot;归档是什么&quot;">​</a></h2><p>归档会话后，对话窗口并没有被删除，而是被移到了历史记录中。</p><p>简单说：归档 = 从侧边栏的活跃列表中隐藏，但对话数据仍然保留。</p><hr><h2 id="归档-vs-删除" tabindex="-1">归档 vs 删除 <a class="header-anchor" href="#归档-vs-删除" aria-label="Permalink to &quot;归档 vs 删除&quot;">​</a></h2><ul><li><strong>归档</strong>：从侧边栏隐藏，数据保留，可以随时恢复。</li><li><strong>删除</strong>：彻底清除，无法恢复。</li><li><strong>取消归档</strong>：放回侧边栏，恢复为活跃会话。</li></ul><hr><h2 id="去哪里查看归档的会话" tabindex="-1">去哪里查看归档的会话 <a class="header-anchor" href="#去哪里查看归档的会话" aria-label="Permalink to &quot;去哪里查看归档的会话&quot;">​</a></h2><ol><li>打开 Codex 桌面 App。</li><li>在侧边栏顶部或账号菜单中，找到「历史记录」或「Archived」入口。</li><li>在列表中可以浏览所有归档的对话。</li><li>找到对应的会话，选择「Unarchive」（取消归档）就能把它放回侧边栏。</li></ol><p>注意：不同版本的 Codex 桌面 App，入口位置可能略有不同。</p><hr><h2 id="典型操作流程" tabindex="-1">典型操作流程 <a class="header-anchor" href="#典型操作流程" aria-label="Permalink to &quot;典型操作流程&quot;">​</a></h2><ol><li>打开 Codex 桌面 App。</li><li>在侧边栏找到需要归档的会话。</li><li>右键或点击会话旁的菜单按钮，选择「Archive」（归档）。</li><li>该会话从侧边栏消失，但数据仍保留在历史记录中。</li><li>需要时，进入历史记录，找到并取消归档。</li></ol><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><hr><h2 id="会话窗口的本质-上下文窗口" tabindex="-1">会话窗口的本质：上下文窗口 <a class="header-anchor" href="#会话窗口的本质-上下文窗口" aria-label="Permalink to &quot;会话窗口的本质：上下文窗口&quot;">​</a></h2><p>每个 Codex 会话本质上是一个上下文窗口。每次新对话都是全新上下文——Codex 不记得之前聊了什么。因此保持单一主题，才能让上下文发挥最大价值。</p><h3 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h3><p>一个会话 = 一个独立任务或主题，比如：</p><ul><li>学习 Codex 笔记整理 → 一个会话</li><li>配置国产 API → 一个会话</li><li>给项目写 AGENTS.md → 一个会话</li><li>排查某个 bug → 一个会话</li></ul><h3 id="什么情况可以在一个会话里聊多个话题" tabindex="-1">什么情况可以在一个会话里聊多个话题 <a class="header-anchor" href="#什么情况可以在一个会话里聊多个话题" aria-label="Permalink to &quot;什么情况可以在一个会话里聊多个话题&quot;">​</a></h3><ul><li>话题之间有关联性（比如聊 Codex 学习路径，然后延伸到 AGENTS.md 写法）</li><li>每个话题都很短，上下文不会被稀释</li><li>你不想维护太多会话</li></ul><h3 id="什么情况应该开新会话" tabindex="-1">什么情况应该开新会话 <a class="header-anchor" href="#什么情况应该开新会话" aria-label="Permalink to &quot;什么情况应该开新会话&quot;">​</a></h3><ul><li>话题完全不相关（比如一边学 Codex，一边调试另一个项目的 bug）</li><li>当前对话已经很长了，上下文被早期内容稀释，后面的问题质量下降</li><li>需要不同的约束或环境（比如一个会话用只读模式分析，另一个要写代码）</li></ul><h3 id="一个实用判断方法" tabindex="-1">一个实用判断方法 <a class="header-anchor" href="#一个实用判断方法" aria-label="Permalink to &quot;一个实用判断方法&quot;">​</a></h3><blockquote><p>如果你发现自己要跟 Codex 重新解释一遍之前的背景，说明这个会话应该拆了。</p></blockquote><h3 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h3><p><strong>按主题分，不按念头分。</strong> 同一个主题下的延伸不需要开新会话，但跨主题就果断拆。</p><ul><li>归档不是删除，只是隐藏。</li><li>随时可以在历史记录中找到并恢复。</li><li>只有主动「删除」才会彻底清除，且不可恢复。</li></ul><hr>',33);function u(x,_,p,b,m,q){const l=o("VPNolebaseInlineLinkPreview");return r(),t("div",null,[c,e("blockquote",null,[e("p",null,[a("📎 "),d(l,{href:"/ocdsync/笔记/"},{default:h(()=>[a("📒 返回笔记索引")]),_:1})])])])}const P=i(s,[["render",u]]);export{f as __pageData,P as default};
